-- ============================================================
-- HR-Core Employee Demo Seed Data
-- PostgreSQL 13+
--
-- Run AFTER hr_core_postgres_ddl.sql.
-- Seeds:
--   * 1 enterprise
--   * 5 departments
--   * 14 positions
--   * 20 employees
--
-- Safe to re-run: parent records use conflict handling and employee
-- records are upserted by (enterprise_id, employee_number).
-- user_id is left NULL because employee login accounts are optional
-- and password hashes should be generated by the application's
-- configured authentication library.
-- ============================================================

BEGIN;

SET search_path TO hr_core, public;

-- ------------------------------------------------------------
-- 1. Enterprise (required parent of departments, positions,
--    and employees)
-- ------------------------------------------------------------

INSERT INTO enterprises (
    company_name,
    company_email,
    tax_number,
    company_address,
    status
)
VALUES (
    'Nusantara Digital Solutions',
    'admin@nusantaradigital.example',
    'NPWP-DEMO-001',
    'Jl. Asia Afrika No. 100, Bandung, West Java, Indonesia',
    'active'
)
ON CONFLICT (LOWER(company_email))
DO UPDATE SET
    company_name    = EXCLUDED.company_name,
    tax_number      = EXCLUDED.tax_number,
    company_address = EXCLUDED.company_address,
    status          = EXCLUDED.status;

-- ------------------------------------------------------------
-- 2. Departments
-- ------------------------------------------------------------

INSERT INTO departments (
    enterprise_id,
    department_name,
    description,
    status
)
SELECT
    e.enterprise_id,
    d.department_name,
    d.description,
    'active'
FROM enterprises e
CROSS JOIN (
    VALUES
        ('Human Resources', 'People operations, recruitment, and employee relations.'),
        ('Engineering',     'Software development, quality assurance, and IT.'),
        ('Finance',         'Accounting, financial planning, and payroll administration.'),
        ('Marketing',       'Brand, campaigns, and digital marketing.'),
        ('Operations',      'Business operations and service delivery.')
) AS d(department_name, description)
WHERE LOWER(e.company_email) = LOWER('admin@nusantaradigital.example')
ON CONFLICT DO NOTHING;

-- ------------------------------------------------------------
-- 3. Positions
-- ------------------------------------------------------------

INSERT INTO positions (
    enterprise_id,
    position_name,
    description
)
SELECT
    e.enterprise_id,
    p.position_name,
    p.description
FROM enterprises e
CROSS JOIN (
    VALUES
        ('HR Manager',                  'Leads the human resources function.'),
        ('HR Specialist',               'Handles employee administration and HR operations.'),
        ('Software Engineer',           'Develops and maintains software applications.'),
        ('Senior Software Engineer',    'Leads technical implementation and development.'),
        ('QA Engineer',                 'Tests software quality and reliability.'),
        ('UI/UX Designer',              'Designs user experiences and interfaces.'),
        ('Finance Manager',             'Oversees finance and accounting operations.'),
        ('Accountant',                  'Maintains financial records and reports.'),
        ('Payroll Specialist',          'Prepares and validates employee payroll.'),
        ('Marketing Manager',           'Leads marketing strategy and campaigns.'),
        ('Digital Marketing Specialist','Executes digital marketing activities.'),
        ('Operations Manager',          'Manages day-to-day business operations.'),
        ('Business Analyst',             'Analyzes business processes and requirements.'),
        ('IT Support Specialist',        'Provides internal technology support.')
) AS p(position_name, description)
WHERE LOWER(e.company_email) = LOWER('admin@nusantaradigital.example')
ON CONFLICT DO NOTHING;

-- ------------------------------------------------------------
-- 4. Employees (20 records)
--    Each department and position is resolved by name and scoped
--    to the demo enterprise to preserve tenant consistency.
-- ------------------------------------------------------------

WITH seed_employees (
    employee_number,
    first_name,
    last_name,
    department_name,
    position_name,
    date_of_birth,
    hire_date,
    employment_status,
    employment_type,
    base_salary,
    bank_account
) AS (
    VALUES
        ('NDS-2026-001', 'Aditya',   'Pratama',  'Human Resources', 'HR Manager',                   DATE '1985-03-14', DATE '2019-01-07', 'active',    'permanent', 18000000.00, 'DEMO-BANK-0001'),
        ('NDS-2026-002', 'Siti',     'Rahmawati','Human Resources', 'HR Specialist',                DATE '1992-07-22', DATE '2021-04-12', 'active',    'permanent',  9500000.00, 'DEMO-BANK-0002'),
        ('NDS-2026-003', 'Budi',     'Santoso',  'Human Resources', 'HR Specialist',                DATE '1994-11-03', DATE '2022-08-01', 'active',    'permanent',  9000000.00, 'DEMO-BANK-0003'),
        ('NDS-2026-004', 'Kevin',    'Wijaya',   'Engineering',     'Senior Software Engineer',    DATE '1988-05-19', DATE '2018-06-18', 'active',    'permanent', 25000000.00, 'DEMO-BANK-0004'),
        ('NDS-2026-005', 'Dewi',     'Anggraini','Engineering',     'Software Engineer',            DATE '1996-02-08', DATE '2022-02-14', 'active',    'permanent', 14500000.00, 'DEMO-BANK-0005'),
        ('NDS-2026-006', 'Rizky',    'Maulana',  'Engineering',     'Software Engineer',            DATE '1995-09-27', DATE '2021-09-06', 'active',    'permanent', 15000000.00, 'DEMO-BANK-0006'),
        ('NDS-2026-007', 'Nadia',    'Putri',    'Engineering',     'QA Engineer',                  DATE '1997-01-16', DATE '2023-01-09', 'active',    'permanent', 12000000.00, 'DEMO-BANK-0007'),
        ('NDS-2026-008', 'Fajar',    'Nugroho',  'Engineering',     'UI/UX Designer',               DATE '1993-12-11', DATE '2020-11-02', 'active',    'permanent', 13500000.00, 'DEMO-BANK-0008'),
        ('NDS-2026-009', 'Maya',     'Permata',  'Engineering',     'Software Engineer',            DATE '1998-04-25', DATE '2024-03-04', 'active',    'contract',   11000000.00, 'DEMO-BANK-0009'),
        ('NDS-2026-010', 'Andi',     'Kurniawan','Finance',         'Finance Manager',              DATE '1984-08-30', DATE '2019-05-13', 'active',    'permanent', 20000000.00, 'DEMO-BANK-0010'),
        ('NDS-2026-011', 'Lestari',  'Wulandari','Finance',         'Accountant',                   DATE '1991-06-17', DATE '2020-07-20', 'active',    'permanent', 11500000.00, 'DEMO-BANK-0011'),
        ('NDS-2026-012', 'Dimas',    'Saputra',  'Finance',         'Payroll Specialist',           DATE '1993-10-05', DATE '2022-05-16', 'active',    'permanent', 12500000.00, 'DEMO-BANK-0012'),
        ('NDS-2026-013', 'Intan',    'Puspita',  'Marketing',       'Marketing Manager',            DATE '1989-02-21', DATE '2020-02-03', 'active',    'permanent', 17500000.00, 'DEMO-BANK-0013'),
        ('NDS-2026-014', 'Rafi',     'Firmansyah','Marketing',      'Digital Marketing Specialist', DATE '1996-07-09', DATE '2023-06-05', 'active',    'permanent', 10500000.00, 'DEMO-BANK-0014'),
        ('NDS-2026-015', 'Citra',    'Larasati', 'Marketing',       'Digital Marketing Specialist', DATE '1997-03-28', DATE '2024-01-15', 'on_leave',  'contract',    9500000.00, 'DEMO-BANK-0015'),
        ('NDS-2026-016', 'Hendra',   'Gunawan',  'Operations',      'Operations Manager',          DATE '1986-09-12', DATE '2019-10-01', 'active',    'permanent', 18500000.00, 'DEMO-BANK-0016'),
        ('NDS-2026-017', 'Putri',    'Amelia',   'Operations',      'Business Analyst',            DATE '1994-04-06', DATE '2021-03-08', 'active',    'permanent', 14000000.00, 'DEMO-BANK-0017'),
        ('NDS-2026-018', 'Yoga',     'Prakoso',  'Operations',      'IT Support Specialist',        DATE '1995-12-19', DATE '2022-10-10', 'active',    'permanent', 10000000.00, 'DEMO-BANK-0018'),
        ('NDS-2026-019', 'Gilang',   'Ramadhan', 'Operations',      'IT Support Specialist',        DATE '1998-08-02', DATE '2025-02-03', 'on_leave',  'intern',      5500000.00, 'DEMO-BANK-0019'),
        ('NDS-2026-020', 'Farah',    'Azzahra',  'Engineering',     'QA Engineer',                  DATE '1999-11-14', DATE '2025-07-01', 'active',    'contract',   10000000.00, 'DEMO-BANK-0020')
)
INSERT INTO employees (
    enterprise_id,
    user_id,
    department_id,
    position_id,
    employee_number,
    first_name,
    last_name,
    date_of_birth,
    hire_date,
    employment_status,
    employment_type,
    base_salary,
    bank_account
)
SELECT
    e.enterprise_id,
    NULL::BIGINT AS user_id,
    d.department_id,
    p.position_id,
    s.employee_number,
    s.first_name,
    s.last_name,
    s.date_of_birth,
    s.hire_date,
    s.employment_status,
    s.employment_type,
    s.base_salary,
    s.bank_account
FROM seed_employees s
JOIN enterprises e
  ON LOWER(e.company_email) = LOWER('admin@nusantaradigital.example')
JOIN departments d
  ON d.enterprise_id = e.enterprise_id
 AND LOWER(d.department_name) = LOWER(s.department_name)
JOIN positions p
  ON p.enterprise_id = e.enterprise_id
 AND LOWER(p.position_name) = LOWER(s.position_name)
ON CONFLICT (enterprise_id, employee_number)
DO UPDATE SET
    department_id     = EXCLUDED.department_id,
    position_id       = EXCLUDED.position_id,
    first_name        = EXCLUDED.first_name,
    last_name         = EXCLUDED.last_name,
    date_of_birth     = EXCLUDED.date_of_birth,
    hire_date         = EXCLUDED.hire_date,
    employment_status = EXCLUDED.employment_status,
    employment_type   = EXCLUDED.employment_type,
    base_salary       = EXCLUDED.base_salary,
    bank_account      = EXCLUDED.bank_account,
    updated_at        = CURRENT_TIMESTAMP;

COMMIT;

-- ------------------------------------------------------------
-- 5. Verification queries
-- ------------------------------------------------------------

-- Expected: 20 seeded employee numbers for this demo enterprise.
SELECT
    e.enterprise_id,
    e.company_name,
    COUNT(emp.employee_id) AS employee_count
FROM enterprises e
LEFT JOIN employees emp
  ON emp.enterprise_id = e.enterprise_id
 AND emp.employee_number LIKE 'NDS-2026-%'
WHERE LOWER(e.company_email) = LOWER('admin@nusantaradigital.example')
GROUP BY e.enterprise_id, e.company_name;

-- Employee List page preview.
SELECT
    employee_number,
    employee_name,
    department_name,
    position_name,
    employment_type,
    employment_status,
    hire_date
FROM v_hr_employee_list
WHERE enterprise_id = (
    SELECT enterprise_id
    FROM enterprises
    WHERE LOWER(company_email) = LOWER('admin@nusantaradigital.example')
)
ORDER BY employee_number;
